  about_bookmarkearth_intro: "BookmarkMars के बारे में",
  about_bookmarkearth_intro_desc: "BookmarkMars Zhihu से प्रेरित है। जब डिज़ाइनर ने संसाधन संबंधी पोस्ट देखी, एक मित्र ने अपने ब्राउज़र बुकमार्क साझा किए और उन्होंने बुकमार्क साझा करने का प्लेटफ़ॉर्म बनाने का विचार किया। बुकमार्क आमतौर पर उपयोगी साइटों को श्रेणियों में व्यवस्थित करते हैं; इसलिए आपके बुकमार्क भी दूसरों के लिए उपयोगी हो सकते हैं। डिज़ाइनर नहीं जानते थे कि यह सभी द्वारा स्वीकार होगा, इसलिए यह एक साहसिक प्रयास था।",
